ime(timestamp){return new Date(timestamp).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}capitalizeFirst(str){return str.charAt(0).toUpperCase()+str.slice(1);}groupDetectionsByDate(detections){const groups={};detections.forEach(detection=>{const date=new Date(detection.detected_at).toDateString();if(!groups[date]){groups[date]=[];}groups[date].push(detection);});return groups;}debounce(func,wait){let timeout;return function executedFunction(...args){const later=()=>{clearTimeout(timeout);func(...args);};clearTimeout(timeout);timeout=setTimeout(later,wait);};}async goToPage(page){const totalPages=Math.ceil(this.pagination.total/this.pagination.limit);if(page < 1 || page > totalPages)return;this.pagination.offset=(page-1)*this.pagination.limit;await this.loadDetections();this.updatePagination();}updatePagination(){const paginationContainer=document.getElementById('detection-pagination');if(paginationContainer){paginationContainer.innerHTML=this.getPaginationTemplate();}}updateResultCount(){const resultsElement=document.getElementById('results-count');if(resultsElement){const count=this.filteredDetections.length;const total=this.detections.length;if(count===0){resultsElement.innerHTML=` <i class="fas fa-search"></i> <span>No results found</span> `;resultsElement.className='results-count empty';}else if(count===total){resultsElement.innerHTML=` <i class="fas fa-list"></i> <span>${count}detection${count !==1 ? 's':''}</span> `;resultsElement.className='results-count';}else{resultsElement.innerHTML=` <i class="fas fa-filter"></i> <span>${count}of ${total}detections</span> `;resultsElement.className='results-count filtered';}}const statusElement=document.getElementById('results-status');if(statusElement){statusElement.innerHTML=this.getResultsStatusTemplate();}}updateStatisticsDisplay(){const dashboardContainer=document.getElementById('stats-dashboard');if(dashboardContainer){dashboardContainer.innerHTML=this.getStatsDashboardTemplate();}}startPeriodicStatsUpdat